function getName(first, second = "hello") {
    "use strict"
    console.log(first === arguments[0]);  // true
    console.log(second === arguments[1]); // true

    first = 'a';
    second = 'b';

    console.log(first === arguments[0]);  // false
    console.log(second === arguments[1]); // false
}
